    content.tracks = serde_json::from_value(json!([{"kind":"image","id":"images","name":"Image","clips":[{"id":"photo","sourceId":"picture","timelineStartTick":0,"durationTicks":1000000,"transform":TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal"}]}])).unwrap();
