#[tokio::test]
async fn nested_export_job_encodes_registers_and_deduplicates_per_owner() {
    use std::process::Command;
    use video_kadr_backend::domain::composition::{CanvasSpec, Composition};
    if !Command::new("ffmpeg").arg("-version").output().is_ok_and(|v|v.status.success()) {eprintln!("FFmpeg unavailable: native export API fixture skipped");return;}
    let (mut state, _directory) = make_state(true,false).await;
    std::sync::Arc::make_mut(&mut state.tools).ffmpeg_encoders.push("ffv1".into());
    std::sync::Arc::make_mut(&mut state.tools).ffmpeg_muxers.push("matroska".into());
    let app = router(state.clone());
    let token = register_token(&app,"native-export-owner").await;
    let other = register_token(&app,"native-export-other").await;
    let mut canvas=CanvasSpec::default();canvas.width=2;canvas.height=2;canvas.fps_milli=2000;canvas.background.blue=1.0;
    let body=json!({"schemaVersion":1,"mode":"video_only","project":{"schemaVersion":1,"root":"root","compositions":{"root":{"durationUs":1000000,"content":Composition::new(canvas),"instances":[]}}},"compositionId":"root","startUs":0,"endUs":1000000});
    let (status,accepted,_)=send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&token)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");
    let id=accepted["jobId"].as_str().unwrap();
    let done=poll_terminal(&app,id).await;
    assert_eq!(done["status"],"done","{done}");
    let result=&done["result"];
    assert_eq!(result["withAudio"],false);assert_eq!(result["videoCodec"],"ffv1");
    let output_id=result["id"].as_str().unwrap();
    assert!(state.db.can_access_output(output_id,"native-export-owner").await.unwrap());
    assert!(!state.db.can_access_output(output_id,"native-export-other").await.unwrap());
    assert!(state.library.get(output_id).await.is_some());
    let decoded=Command::new("ffmpeg").args(["-v","error","-i"]).arg(state.outputs_dir().join(result["filename"].as_str().unwrap())).args(["-f","rawvideo","-pix_fmt","rgba","pipe:1"]).output().unwrap();
    assert!(decoded.status.success());assert_eq!(decoded.stdout,[0,0,255,255].repeat(8));
    let (_,repeat,_)=send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&token)).await;
    assert_eq!(repeat["jobId"],accepted["jobId"]);
    let (status,separate,_)=send(&app,bearer(post_json("/api/compositions/nested-export",body),&other)).await;
    assert_eq!(status,StatusCode::ACCEPTED);assert_ne!(separate["jobId"],accepted["jobId"]);
    assert_eq!(poll_terminal(&app,separate["jobId"].as_str().unwrap()).await["status"],"done");
}

#[tokio::test]
async fn nested_export_checks_private_sources_and_rendered_output_access() {
    use video_kadr_backend::domain::composition::{CanvasSpec,Composition,TransformSpec};
    let (mut state,_directory)=make_state(true,false).await;
    std::sync::Arc::make_mut(&mut state.tools).ffmpeg_encoders.push("ffv1".into());
    std::sync::Arc::make_mut(&mut state.tools).ffmpeg_muxers.push("matroska".into());
    image::RgbaImage::from_raw(2,2,[0,0,255,255].repeat(4)).unwrap().save(state.sources_dir().join("private.png")).unwrap();
    assert!(state.library.add(MediaEntry::from_result("source",&json!({"id":"private-picture","filename":"private.png","url":"/files/sources/private.png","mediaType":"image"}))).await);
    let app=router(state.clone());
    let owner=register_token(&app,"export-private-owner").await;
    let stranger=register_token(&app,"export-private-stranger").await;
    let mut canvas=CanvasSpec::default();canvas.width=2;canvas.height=2;canvas.fps_milli=2000;
    let mut content=Composition::new(canvas);
    content.sources=serde_json::from_value(json!({"private-picture":{"id":"private-picture","kind":"image","durationTicks":0,"width":2,"height":2,"hasAudio":false}})).unwrap();
    content.tracks=serde_json::from_value(json!([{"kind":"image","id":"images","name":"Images","clips":[{"id":"image","sourceId":"private-picture","timelineStartTick":0,"durationTicks":1000000,"transform":TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal"}]}])).unwrap();
    let project=json!({"schemaVersion":1,"root":"root","compositions":{"root":{"durationUs":1000000,"content":content,"instances":[]}}});
    let (status,space,_)=send(&app,bearer(post_json("/api/spaces",json!({"name":"Private export"})),&owner)).await;
    assert_eq!(status,StatusCode::CREATED);
    let (status,saved,_)=send(&app,bearer(post_json("/api/composition-projects",json!({"schemaVersion":2,"mode":"composition","spaceId":space["id"],"name":"Private export","document":project})),&owner)).await;
    assert_eq!(status,StatusCode::CREATED,"{saved}");
    let mut body=json!({"schemaVersion":1,"mode":"video_only","project":project,"compositionId":"root","startUs":0,"endUs":1000000});
    assert_eq!(send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&stranger)).await.0,StatusCode::FORBIDDEN);
    let output=uuid::Uuid::new_v4().to_string();
    tokio::fs::write(state.outputs_dir().join(format!("{output}.mkv")),b"owned output").await.unwrap();
    state.db.grant_output_access(&output,"export-private-owner").await.unwrap();
    body["renderedOutputs"]=json!({"root":output});
    assert_eq!(send(&app,bearer(post_json("/api/compositions/nested-export",body),&stranger)).await.0,StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn nested_durations_returns_native_explicit_bounds_and_rejects_missing_root() {
    use video_kadr_backend::domain::composition::{CanvasSpec,Composition};
    let (state,_directory)=make_state(false,false).await;
    let app=router(state);
    let mut project=json!({"schemaVersion":1,"root":"root","compositions":{"root":{"durationUs":750000,"content":Composition::new(CanvasSpec::default()),"instances":[]}}});
    let (status,durations,_)=send(&app,post_json("/api/compositions/nested-durations",json!({"project":project}))).await;
    assert_eq!(status,StatusCode::OK);assert_eq!(durations,json!({"root":750000}));
    project["root"]=json!("missing");
    assert_eq!(send(&app,post_json("/api/compositions/nested-durations",json!({"project":project}))).await.0,StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn nested_audio_export_authorizes_sources_probes_real_channels_and_publishes_lossless_av() {
    use std::process::Command;
    use video_kadr_backend::domain::composition::{CanvasSpec,Composition};
    for tool in ["ffmpeg","ffprobe"] {if !Command::new(tool).arg("-version").output().is_ok_and(|v|v.status.success()){eprintln!("{tool} unavailable: native audio export API fixture skipped");return}}
    let (mut state,_directory)=make_state(true,false).await;
    let tools=std::sync::Arc::make_mut(&mut state.tools);tools.ffmpeg_encoders.extend(["ffv1".into(),"pcm_f32le".into()]);tools.ffmpeg_muxers.push("matroska".into());
    let bytes=24000u32*4;let mut wav=Vec::new();wav.extend(b"RIFF");wav.extend((36+bytes).to_le_bytes());wav.extend(b"WAVEfmt ");wav.extend(16u32.to_le_bytes());wav.extend(1u16.to_le_bytes());wav.extend(2u16.to_le_bytes());wav.extend(48000u32.to_le_bytes());wav.extend(192000u32.to_le_bytes());wav.extend(4u16.to_le_bytes());wav.extend(16u16.to_le_bytes());wav.extend(b"data");wav.extend(bytes.to_le_bytes());
    for _ in 0..24000 {wav.extend(8192i16.to_le_bytes());wav.extend((-8192i16).to_le_bytes());}
    std::fs::write(state.sources_dir().join("audio-export.wav"),wav).unwrap();
    assert!(state.library.add(MediaEntry::from_result("source",&json!({"id":"private-audio","filename":"audio-export.wav","url":"/files/sources/audio-export.wav","mediaType":"audio"}))).await);
    let app=router(state.clone());let owner=register_token(&app,"native-audio-owner").await;let stranger=register_token(&app,"native-audio-stranger").await;
    let mut canvas=CanvasSpec::default();canvas.width=2;canvas.height=2;canvas.fps_milli=2000;canvas.background.blue=1.0;
    let mut content=Composition::new(canvas);
    // Authored channel metadata deliberately disagrees with the real stereo file.
    content.sources=serde_json::from_value(json!({"private-audio":{"id":"private-audio","kind":"audio","durationTicks":1000000,"width":0,"height":0,"hasAudio":true,"audioChannels":1}})).unwrap();
    content.tracks=serde_json::from_value(json!([{"kind":"audio","id":"audio","name":"Audio","clips":[{"id":"clip","sourceId":"private-audio","placement":{"timelineStartTick":0,"sourceInTick":0,"sourceOutTick":1000000,"speed":1.0},"gain":{"mode":"constant","value":1.0},"pan":{"mode":"constant","value":0.0},"fadeInTicks":0,"fadeOutTicks":0}]}])).unwrap();
    let project=json!({"schemaVersion":1,"root":"root","compositions":{"root":{"durationUs":1000000,"content":content,"instances":[]}}});
    let (status,space,_)=send(&app,bearer(post_json("/api/spaces",json!({"name":"Private audio"})),&owner)).await;assert_eq!(status,StatusCode::CREATED);
    let (status,saved,_)=send(&app,bearer(post_json("/api/composition-projects",json!({"schemaVersion":2,"mode":"composition","name":"Private audio","spaceId":space["id"],"document":project})),&owner)).await;assert_eq!(status,StatusCode::CREATED,"{saved}");
    let mut body=json!({"schemaVersion":1,"mode":"video_audio","project":project,"compositionId":"root","startUs":0,"endUs":1000000});
    assert_eq!(send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&stranger)).await.0,StatusCode::FORBIDDEN);
    let (status,accepted,_)=send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");assert_eq!(accepted["mode"],"video_audio");
    let done=poll_terminal(&app,accepted["jobId"].as_str().unwrap()).await;assert_eq!(done["status"],"done","{done}");let result=&done["result"];
    assert_eq!(result["withAudio"],true);assert_eq!(result["audioCodec"],"pcm_f32le");assert_eq!(result["mode"],"video_audio");
    assert!(state.library.get(result["id"].as_str().unwrap()).await.is_some());assert!(state.db.can_access_output(result["id"].as_str().unwrap(),"native-audio-owner").await.unwrap());assert!(!state.db.can_access_output(result["id"].as_str().unwrap(),"native-audio-stranger").await.unwrap());
    let output=state.outputs_dir().join(result["filename"].as_str().unwrap());
    let audio=Command::new("ffmpeg").args(["-v","error","-i"]).arg(&output).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();assert!(audio.status.success());
    let mut expected=Vec::new();for _ in 0..24000 {expected.extend(0.25f32.to_le_bytes());expected.extend((-0.25f32).to_le_bytes());}expected.extend(vec![0u8;24000*8]);assert_eq!(audio.stdout,expected);
    let video=Command::new("ffmpeg").args(["-v","error","-i"]).arg(&output).args(["-map","0:v:0","-pix_fmt","rgba","-f","rawvideo","pipe:1"]).output().unwrap();assert!(video.status.success());assert_eq!(video.stdout,[0,0,255,255].repeat(8));
    let (_,repeated,_)=send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;assert_eq!(repeated["jobId"],accepted["jobId"]);
    body["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["dspEffects"]=json!([{"id":"invert"}]);
    let (status, dsp_job, _) = send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{dsp_job}");
    let dsp_done = poll_terminal(&app,dsp_job["jobId"].as_str().unwrap()).await;
    assert_eq!(dsp_done["status"],"done","{dsp_done}");
    let dsp_output = state.outputs_dir().join(dsp_done["result"]["filename"].as_str().unwrap());
    let decoded = Command::new("ffmpeg").args(["-v","error","-i"]).arg(&dsp_output).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();
    assert!(decoded.status.success());
    let mut inverted = Vec::new();
    for _ in 0..24000 { inverted.extend((-0.25f32).to_le_bytes()); inverted.extend(0.25f32.to_le_bytes()); }
    inverted.extend(vec![0u8;24000*8]);
    assert_eq!(decoded.stdout,inverted);
    let mut short = body.clone(); short["endUs"] = json!(250000);
    let (status, selected_job, _) = send(&app,bearer(post_json("/api/compositions/nested-export",short),&owner)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{selected_job}");
    let selected_done = poll_terminal(&app,selected_job["jobId"].as_str().unwrap()).await;
    assert_eq!(selected_done["status"],"done","{selected_done}");
    let selected_path = state.outputs_dir().join(selected_done["result"]["filename"].as_str().unwrap());
    let selected_pcm = Command::new("ffmpeg").args(["-v","error","-i"]).arg(&selected_path).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();
    assert!(selected_pcm.status.success());
    let mut selected_expected = Vec::new();
    for _ in 0..12000 { selected_expected.extend((-0.25f32).to_le_bytes()); selected_expected.extend(0.25f32.to_le_bytes()); }
    selected_expected.extend(vec![0u8;12000*8]);
    assert_eq!(selected_pcm.stdout,selected_expected);
    body["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["dspEffects"]=json!([{"id":"fft_filter"}]);
    let (status, latency_job, _) = send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{latency_job}");
    let latency_done = poll_terminal(&app,latency_job["jobId"].as_str().unwrap()).await;
    assert_eq!(latency_done["status"],"done","{latency_done}");
    let latency_path = state.outputs_dir().join(latency_done["result"]["filename"].as_str().unwrap());
    let latency_pcm = Command::new("ffmpeg").args(["-v","error","-i"]).arg(&latency_path).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();
    assert!(latency_pcm.status.success());
    let mut reference = filmcraft_audio_dsp::create_effect("fft_filter",48000.0,2).unwrap();
    assert_eq!(reference.latency(),2048);
    let pre = 5760usize; // Source DIRECT max(100ms,120ms smoothing),48kHz.
    let input_start = 2048i64 - pre as i64;
    let mut left:Vec<f32> = (0..pre+48000).map(|i| if (0..24000).contains(&(input_start+i as i64)) {0.25} else {0.0}).collect();
    let mut right:Vec<f32> = left.iter().map(|v| -*v).collect();
    reference.process(&mut [&mut left,&mut right]);
    let oracle:Vec<f32> = (pre..pre+48000).flat_map(|i| [left[i],right[i]]).collect();
    let actual:Vec<f32> = latency_pcm.stdout.chunks_exact(4).map(|v| f32::from_le_bytes(v.try_into().unwrap())).collect();
    assert_eq!(actual.len(),oracle.len());
    for (index,(actual,expected)) in actual.iter().zip(&oracle).enumerate() {
        assert_eq!(actual,expected,"FFT compensated sample {index}");
    }


    body["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["dspEffects"]=json!([{"id":"amplify","animation":{"gain":{"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0.0},{"tick":500000,"value":-6.0}]}}}}]);
    let (status, automation_job, _) = send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{automation_job}");
    let automation_done = poll_terminal(&app,automation_job["jobId"].as_str().unwrap()).await;
    assert_eq!(automation_done["status"],"done","{automation_done}");
    let automation_path = state.outputs_dir().join(automation_done["result"]["filename"].as_str().unwrap());
    let automation_pcm = Command::new("ffmpeg").args(["-v","error","-i"]).arg(&automation_path).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();
    assert!(automation_pcm.status.success());
    let mut native_gain = filmcraft_audio_dsp::create_effect("amplify",48000.0,2).unwrap();
    let mut gain_left=vec![0.0f32;48000]; gain_left[..24000].fill(0.25);
    let mut gain_right=vec![0.0f32;48000]; gain_right[..24000].fill(-0.25);
    for grid in (0..48000).step_by(256) {
        let tick=(grid as f64 / 48000.0 * 1000000.0).round();
        let target=(-6.0 * (tick / 500000.0).min(1.0)) as f32;
        assert!(native_gain.set_param("gain",target));
        let end=(grid+256).min(48000);
        native_gain.process(&mut [&mut gain_left[grid..end],&mut gain_right[grid..end]]);
    }
    let gain_oracle:Vec<f32>=(0..48000).flat_map(|i| [gain_left[i],gain_right[i]]).collect();
    let gain_actual:Vec<f32>=automation_pcm.stdout.chunks_exact(4).map(|v| f32::from_le_bytes(v.try_into().unwrap())).collect();
    assert_eq!(gain_actual.len(),gain_oracle.len());
    for (index,(actual,expected)) in gain_actual.iter().zip(&gain_oracle).enumerate() {
        assert_eq!(actual,expected,"automated gain sample {index}");
    }

    // Same automation through source project-id dispatch must retain exact gain PCM.
    body["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["dspEffects"][0]["id"] = json!("filmcraft:amplify");
    let (status, project_gain_job, _) = send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{project_gain_job}");
    let project_gain_done = poll_terminal(&app,project_gain_job["jobId"].as_str().unwrap()).await;
    assert_eq!(project_gain_done["status"],"done","{project_gain_done}");
    let project_gain_path = state.outputs_dir().join(project_gain_done["result"]["filename"].as_str().unwrap());
    let project_gain_pcm = Command::new("ffmpeg").args(["-v","error","-i"]).arg(&project_gain_path).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();
    assert!(project_gain_pcm.status.success());
    assert_eq!(project_gain_pcm.stdout, automation_pcm.stdout, "source-id automated gain must equal qualified direct native export");

    // Source delay is seconds; native DSP time is milliseconds. Build the oracle independently.
    body["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["dspEffects"] = json!([{"id":"filmcraft:delay","params":{"delay":0.1,"feedback":0.0,"mix":50.0}}]);
    let (status, project_delay_job, _) = send(&app,bearer(post_json("/api/compositions/nested-export",body.clone()),&owner)).await;
    assert_eq!(status,StatusCode::ACCEPTED,"{project_delay_job}");
    let project_delay_done = poll_terminal(&app,project_delay_job["jobId"].as_str().unwrap()).await;
    assert_eq!(project_delay_done["status"],"done","{project_delay_done}");
    let project_delay_path = state.outputs_dir().join(project_delay_done["result"]["filename"].as_str().unwrap());
    let project_delay_pcm = Command::new("ffmpeg").args(["-v","error","-i"]).arg(&project_delay_path).args(["-map","0:a:0","-c:a","pcm_f32le","-f","f32le","pipe:1"]).output().unwrap();
    assert!(project_delay_pcm.status.success());
    let delay_pre = (f64::from(0.1f32) * 48000.0).ceil() as usize;
    let mut delay_left = vec![0.0f32; delay_pre + 48000];
    delay_left[delay_pre..delay_pre+24000].fill(0.25);
    let mut delay_right: Vec<f32> = delay_left.iter().map(|v| -*v).collect();
    let mut delay_reference = filmcraft_audio_dsp::create_effect("delay", 48000.0, 2).unwrap();
    assert!(delay_reference.set_param("time", 0.1f32 * 1000.0));
    assert!(delay_reference.set_param("feedback", 0.0));
    assert!(delay_reference.set_param("mix", 50.0));
    delay_reference.process(&mut [&mut delay_left, &mut delay_right]);
    let delay_expected: Vec<f32> = (delay_pre..delay_pre+48000).flat_map(|i| [delay_left[i],delay_right[i]]).collect();
    let delay_actual: Vec<f32> = project_delay_pcm.stdout.chunks_exact(4).map(|v| f32::from_le_bytes(v.try_into().unwrap())).collect();
    assert_eq!(delay_actual.len(), delay_expected.len());
    for (index,(actual,expected)) in delay_actual.iter().zip(&delay_expected).enumerate() {
        assert_eq!(actual,expected,"source delay sample {index}");
    }
    assert!(delay_actual[48000..57600].iter().any(|v| v.abs() > 0.01), "real delay tail after source silence");

    body["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["voiceEffect"]=json!("echo");
    assert_eq!(send(&app,bearer(post_json("/api/compositions/nested-export",body),&owner)).await.0,StatusCode::BAD_REQUEST);
    assert!(!std::fs::read_dir(state.outputs_dir()).unwrap().any(|v|{let n=v.unwrap().file_name();n.to_string_lossy().starts_with(".pcm-")||n.to_string_lossy().starts_with(".mix-")||n.to_string_lossy().starts_with(".raster-")}));
}

