#[tokio::test]
async fn native_color_match_resolves_shared_project_tables() {
 let (state,_directory)=make_state(false,false).await;let app=router(state);
 let frame=json!({"width":2,"height":1,"rgba":[80,120,160,255,140,100,70,128]});
 let lut=json!({"format":"cube","text":"LUT_1D_SIZE 2\n0.05 0.1 0.15\n0.9 0.85 0.8\n","intensity":100});
 let inline=json!({"current":frame,"reference":frame,"parameters":{"lookLut":lut},"skinProtect":true});
 let (status,expected,_)=send(&app,post_json("/api/compositions/color-match",inline)).await;
 assert_eq!(status,StatusCode::OK,"{expected}");
 let linked=json!({"current":frame,"reference":frame,"parameters":{"lookLutLibrary":"shared"},"luts":[{"id":"shared","name":"Shared","lut":lut}],"skinProtect":true});
 let (status,actual,_)=send(&app,post_json("/api/compositions/color-match",linked.clone())).await;
 assert_eq!(status,StatusCode::OK,"{actual}");assert_eq!(actual,expected);
 let mut missing=linked.clone();missing["luts"]=json!([]);
 assert_eq!(send(&app,post_json("/api/compositions/color-match",missing)).await.0,StatusCode::OK);
 let mut duplicate=linked.clone();duplicate["luts"].as_array_mut().unwrap().push(linked["luts"][0].clone());
 assert_eq!(send(&app,post_json("/api/compositions/color-match",duplicate)).await.0,StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn native_project_lut_import_assigns_reuses_and_respects_locks() {
 let (state,_directory)=make_state(false,false).await;let app=router(state);
 let mut composition=video_kadr_backend::domain::composition::Composition::new(video_kadr_backend::domain::composition::CanvasSpec::default());
 composition.sources=serde_json::from_value(json!({"source":{"id":"source","kind":"video","durationTicks":1000000,"width":2,"height":2,"hasAudio":false}})).unwrap();
 composition.tracks=serde_json::from_value(json!([{"kind":"video","id":"v","name":"Video","clips":[{"id":"clip","sourceId":"source","placement":{"timelineStartTick":0,"sourceInTick":0,"sourceOutTick":1000000,"speed":1.0},"transform":video_kadr_backend::domain::composition::TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal","effects":[{"kind":"lumetri","parameters":{"basic":{"exposure":1.5}}}]}]}])).unwrap();
 let project=json!({"schemaVersion":1,"root":"root","compositions":{"root":{"content":composition,"instances":[]}}});
 let mut request=json!({"project":project,"lut":{"format":"cube","text":"LUT_1D_SIZE 2\n0 0 0\n1 1 1\n","intensity":100},"name":"Identity","sourcePath":"identity.cube","composition":"root","track":"v","clip":"clip","effectIndex":0,"input":false});
 let (status,first,_)=send(&app,post_json("/api/compositions/project-lut-import",request.clone())).await;
 assert_eq!(status,StatusCode::OK,"{first}");assert_eq!(first["id"],"lut1");assert_eq!(first["reused"],false);
 assert_eq!(first["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["effects"][0]["parameters"]["lookLutLibrary"],"lut1");
 assert_eq!(first["project"]["compositions"]["root"]["content"]["tracks"][0]["clips"][0]["effects"][0]["parameters"]["basic"]["exposure"],1.5);
 request["project"]=first["project"].clone();request["name"]=json!("Other name");
 let (status,reused,_)=send(&app,post_json("/api/compositions/project-lut-import",request.clone())).await;
 assert_eq!(status,StatusCode::OK,"{reused}");assert_eq!(reused["reused"],true);assert_eq!(reused["project"]["luts"].as_array().unwrap().len(),1);assert_eq!(reused["project"]["luts"][0]["name"],"Identity");
 let inverse=json!({"format":"cube","text":"LUT_1D_SIZE 2\n1 1 1\n0 0 0\n","intensity":100.0});
 let (status,updated,_)=send(&app,post_json("/api/compositions/project-lut-update",json!({"project":reused["project"],"id":"lut1","name":"Inverse","lut":inverse,"sourcePath":"inverse.cube"}))).await;
 assert_eq!(status,StatusCode::OK,"{updated}");assert_eq!(updated["luts"][0]["id"],"lut1");assert_eq!(updated["luts"][0]["name"],"Inverse");assert_eq!(updated["luts"][0]["lut"],inverse);
 assert_eq!(updated["compositions"],reused["project"]["compositions"]);
 assert_eq!(send(&app,post_json("/api/compositions/project-lut-update",json!({"project":updated,"id":"lut1","name":""}))).await.0,StatusCode::BAD_REQUEST);
 let (status,removed,_)=send(&app,post_json("/api/compositions/project-lut-remove",json!({"project":updated,"id":"lib:lut1"}))).await;
 assert_eq!(status,StatusCode::OK,"{removed}");assert!(removed.get("luts").is_none());assert_eq!(removed["compositions"],updated["compositions"]);
 let mut fresh=request.clone();fresh["project"]=removed.clone();
 let (status,imported,_)=send(&app,post_json("/api/compositions/project-lut-import",fresh)).await;
 assert_eq!(status,StatusCode::OK,"{imported}");assert_eq!(imported["id"],"lut2");
 assert_eq!(send(&app,post_json("/api/compositions/project-lut-remove",json!({"project":removed,"id":"lut1"}))).await.0,StatusCode::BAD_REQUEST);
 request["project"]["compositions"]["root"]["content"]["tracks"][0]["locked"]=json!(true);
 assert_eq!(send(&app,post_json("/api/compositions/project-lut-import",request)).await.0,StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn native_lut_export_roundtrips_library_and_builtin_tables() {
 use video_kadr_backend::domain::lut_tables::{Lut,LutFormat};
 let (state,_directory)=make_state(false,false).await;let app=router(state);
 let lut=json!({"format":"cube","text":"TITLE \"Identity\"\nLUT_1D_SIZE 2\n0 0 0\n1 1 1\n","intensity":100});
 for (format,parser) in [("cube",LutFormat::Cube),("three_dl",LutFormat::ThreeDl)] {
  let request=json!({"luts":[{"id":"shared","name":"Shared","lut":lut}],"reference":"lib:shared","format":format});
  let (status,result,_)=send(&app,post_json("/api/compositions/lut-export",request)).await;
  assert_eq!(status,StatusCode::OK,"{result}");
  let parsed=Lut::parse(result["text"].as_str().unwrap(),Some(parser)).unwrap();
  for input in [[0.0,0.0,0.0],[0.25,0.5,0.75],[1.0,1.0,1.0]] {
   let actual=parsed.apply(input);assert!((0..3).all(|c|(actual[c]-input[c]).abs()<0.0005));
  }
  assert!(result["filename"].as_str().unwrap().starts_with("Identity."));
 }
 let (status,builtin,_)=send(&app,post_json("/api/compositions/lut-export",json!({"reference":"builtin:slog3-sgamut3cine-to-rec709","format":"cube"}))).await;
 assert_eq!(status,StatusCode::OK,"{builtin}");
 let parsed=Lut::parse(builtin["text"].as_str().unwrap(),Some(LutFormat::Cube)).unwrap();
 let original=video_kadr_backend::domain::builtin_luts::resolve("slog3-sgamut3cine-to-rec709").unwrap();
 for input in [[0.0,0.0,0.0],[0.41,0.32,0.7],[1.0,1.0,1.0]] {
  let actual=parsed.apply(input);let expected=original.apply(input);
  // Cube exporter writes six decimal places, preserving samples within rounding error.
  assert!((0..3).all(|c|(actual[c]-expected[c]).abs()<0.000001));
 }
 for request in [json!({"format":"cube"}),json!({"reference":"","format":"cube"}),json!({"reference":"lib:missing","format":"cube"}),json!({"reference":"builtin:missing","lut":lut,"format":"cube"})] {
  assert_eq!(send(&app,post_json("/api/compositions/lut-export",request)).await.0,StatusCode::BAD_REQUEST);
 }
}

#[tokio::test]
async fn composition_project_with_luts_over_two_mib_saves_loads_updates_and_evaluates() {
 use video_kadr_backend::domain::composition::{CanvasSpec,Composition};
 let (state,_directory)=make_state(true,true).await;let app=router(state);let token=register_token(&app,"large-lut-owner").await;
 let text=format!("{}LUT_1D_SIZE 2\n0 0 0\n1 1 1\n",format!("#{}\n","x".repeat(1000)).repeat(2200));
 let mut document=json!({"schemaVersion":1,"root":"root","luts":[{"id":"shared","name":"Large identity","lut":{"format":"cube","text":text,"intensity":100}}],"compositions":{"root":{"content":Composition::new(CanvasSpec::default()),"instances":[]}}});
 assert!(serde_json::to_vec(&document).unwrap().len()>MAX_COMPOSITION_PROJECT_DOCUMENT_BYTES);
 let envelope=|document:Value,revision:Option<u64>|json!({"schemaVersion":2,"mode":"composition","name":"Large LUT","document":document,"baseRevision":revision});
 let (status,created,_)=send(&app,bearer(post_json("/api/composition-projects",envelope(document.clone(),None)),&token)).await;
 assert_eq!(status,StatusCode::CREATED,"{created}");
 let path=format!("/api/composition-projects/{}",created["id"].as_str().unwrap());
 let (status,loaded,_)=send(&app,bearer(get(&path),&token)).await;assert_eq!(status,StatusCode::OK);assert_eq!(loaded["document"],document);
 document["luts"][0]["name"]=json!("Renamed identity");
 let (status,updated,_)=send(&app,bearer(put_json(&path,envelope(document.clone(),loaded["revision"].as_u64())),&token)).await;
 assert_eq!(status,StatusCode::OK,"{updated}");assert_eq!(updated["document"],document);
 let (status,result,_)=send(&app,post_json("/api/compositions/nested-frame",json!({"project":document,"timeUs":0}))).await;
 assert_eq!(status,StatusCode::OK,"{result}");
}

