    for (start,expected) in [(1000000,[63u8,63,63,255]),(1500000,[63u8,63,63,255])] {
        let body=json!({"schemaVersion":1,"composition":monochrome,"output":{"profile":{"container":"mp4","codec":"h264"},"range":{"startTicks":start,"endTicks":2000000}}});
        let (status,accepted,_)=send(&app,post_json("/api/compositions/render",body.clone())).await;
        assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");
        let done=poll_terminal(&app,accepted["jobId"].as_str().unwrap()).await;
        assert_eq!(done["status"],"done","Black & White image export: {done}");
        let output=state.outputs_dir().join(done["result"]["filename"].as_str().unwrap());
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&output,0,16,16).unwrap();
        for pixel in frame.rgba.chunks_exact(4) {for (actual,expected) in pixel.iter().zip(expected) {
            assert!((i16::from(*actual)-i16::from(expected)).abs()<=4,"Black & White selected image at {start}: {pixel:?}");
        }}
        let (_,reused,_)=send(&app,post_json("/api/compositions/render",body)).await;
        assert_eq!(reused["jobId"],accepted["jobId"]);
    }
    let tint_curve=json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0},{"tick":500000,"value":1}]}});
    let mut tinted=serde_json::to_value(&content).unwrap();
    tinted["tracks"][0]["clips"][0]["effects"]=json!([{"kind":"color_tint","parameters":{"black":[0,0,0,0],"white":[0,0,0,0]},"colorAnimation":{"blackR":tint_curve,"whiteR":tint_curve}}]);
    for (start,expected) in [(1000000,[0u8,0,0,255]),(1250000,[64u8,0,0,255]),(1500000,[128u8,0,0,255])] {
        let body=json!({"schemaVersion":1,"composition":tinted,"output":{"profile":{"container":"mp4","codec":"h264"},"range":{"startTicks":start,"endTicks":2000000}}});
        let (status,accepted,_)=send(&app,post_json("/api/compositions/render",body.clone())).await;
        assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");
        let done=poll_terminal(&app,accepted["jobId"].as_str().unwrap()).await;
        assert_eq!(done["status"],"done","Tint image export: {done}");
        let output=state.outputs_dir().join(done["result"]["filename"].as_str().unwrap());
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&output,0,16,16).unwrap();
        for pixel in frame.rgba.chunks_exact(4) {for (actual,expected) in pixel.iter().zip(expected) {
            assert!((i16::from(*actual)-i16::from(expected)).abs()<=4,"Tint selected image at {start}: {pixel:?}");
        }}
        let (_,reused,_)=send(&app,post_json("/api/compositions/render",body)).await;
        assert_eq!(reused["jobId"],accepted["jobId"]);
    }
    let balance_curve=json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0},{"tick":500000,"value":100}]}});
    let mut balanced=serde_json::to_value(&content).unwrap();
    balanced["tracks"][0]["clips"][0]["effects"]=json!([{"kind":"color_balance","parameters":{},"animation":{"shadowR":balance_curve}}]);
    for (preserve,start,expected) in [(false,1000000,[32u8,64,96,255]),(false,1250000,[37u8,64,96,255]),(false,1500000,[41u8,64,96,255]),(true,1000000,[32u8,64,96,255]),(true,1250000,[36u8,63,95,255]),(true,1500000,[39u8,62,94,255])] {
        balanced["tracks"][0]["clips"][0]["effects"][0]["parameters"]["preserve"]=json!(preserve);
        let body=json!({"schemaVersion":1,"composition":balanced,"output":{"profile":{"container":"mp4","codec":"h264"},"range":{"startTicks":start,"endTicks":2000000}}});
        let (status,accepted,_)=send(&app,post_json("/api/compositions/render",body.clone())).await;
        assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");
        let done=poll_terminal(&app,accepted["jobId"].as_str().unwrap()).await;
        assert_eq!(done["status"],"done","Color Balance image export: {done}");
        let output=state.outputs_dir().join(done["result"]["filename"].as_str().unwrap());
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&output,0,16,16).unwrap();
        for pixel in frame.rgba.chunks_exact(4) {for (actual,expected) in pixel.iter().zip(expected) {
            assert!((i16::from(*actual)-i16::from(expected)).abs()<=4,"Color Balance selected image at {start}: {pixel:?}");
        }}
        let (_,reused,_)=send(&app,post_json("/api/compositions/render",body)).await;
        assert_eq!(reused["jobId"],accepted["jobId"]);
    }
    let leave_curve=json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0},{"tick":500000,"value":100}]}});
    let mut decolored=serde_json::to_value(&content).unwrap();
