#[tokio::test]
async fn ordinary_image_ultra_key_curves_export_selected_local_clock() {
    use video_kadr_backend::domain::composition::{CanvasSpec, Composition, TransformSpec};
    for tool in ["ffmpeg", "ffprobe"] {
        assert!(std::process::Command::new(tool).arg("-version").output().unwrap().status.success());
    }
    let (state, _directory) = make_state(true, true).await;
    image::RgbaImage::from_raw(16,16,[64,128,192,128].repeat(256)).unwrap()
        .save(state.sources_dir().join("effect-image.png")).unwrap();
    assert!(state.library.add(MediaEntry::from_result("source", &json!({"id":"effect-image","filename":"effect-image.png","url":"/files/sources/effect-image.png","mediaType":"image"}))).await);
    let mut canvas=CanvasSpec::default();canvas.width=16;canvas.height=16;canvas.fps_milli=10000;
    let mut content=Composition::new(canvas);
    content.sources=serde_json::from_value(json!({"effect-image":{"id":"effect-image","kind":"image","durationTicks":0,"width":16,"height":16,"hasAudio":false}})).unwrap();
    content.tracks=serde_json::from_value(json!([{"kind":"image","id":"images","name":"Images","clips":[{"id":"photo","sourceId":"effect-image","timelineStartTick":1000000,"durationTicks":1000000,"transform":TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal","effects":[{"kind":"gamma_correction","parameters":{},"animation":{"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":10.0},{"tick":500000,"value":20.0}]}}}]}]}])).unwrap();
    let app=router(state.clone());
    let oracle:Value=serde_json::from_str(include_str!("fixtures/filmcraft-ultra-key.json")).unwrap();
    assert_eq!(oracle["media"].as_array().unwrap().len(),9);
    let curve=json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0},{"tick":500000,"value":100}]}});
    let mut keyed=serde_json::to_value(&content).unwrap();
    for case in oracle["media"].as_array().unwrap() {
        keyed["tracks"][0]["clips"][0]["effects"]=json!([{"kind":"ultra_key","parameters":{"output":case["output"]},"animation":{"spill":curve}}]);
        let start=1000000+case["localTick"].as_u64().unwrap();
        let bits:Vec<u32>=serde_json::from_value(case["bits"].clone()).unwrap();let a=f32::from_bits(bits[3]);
        let alpha=(a*255.0+1e-4).round().clamp(0.0,255.0);
        let rgb:[u8;3]=std::array::from_fn(|c| {
            if a<=1e-6 {return 0;}
            let v=(f32::from_bits(bits[c])/a).max(0.0);
            let display=if v<=0.0031308 {v*12.92}else{1.055*v.powf(1.0/2.4)-0.055};
            (((display*255.0+1e-4).round().clamp(0.0,255.0))*alpha/255.0).round() as u8
        });
        let body=json!({"schemaVersion":1,"composition":keyed,"output":{"profile":{"container":"mp4","codec":"h264"},"range":{"startTicks":start,"endTicks":2000000}}});
        let (status,accepted,_)=send(&app,post_json("/api/compositions/render",body.clone())).await;
        assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");
        let done=poll_terminal(&app,accepted["jobId"].as_str().unwrap()).await;
        assert_eq!(done["status"],"done","Ultra Key image export: {done}");
        let output=state.outputs_dir().join(done["result"]["filename"].as_str().unwrap());
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&output,0,16,16).unwrap();
        for pixel in frame.rgba.chunks_exact(4) {for(actual,expected)in pixel[..3].iter().zip(rgb){assert!((i16::from(*actual)-i16::from(expected)).abs()<=4,"Ultra Key output {} selected {start}: {pixel:?} expected {rgb:?}",case["output"]);}assert_eq!(pixel[3],255);}
        let (_,reused,_)=send(&app,post_json("/api/compositions/render",body)).await;
        assert_eq!(reused["jobId"],accepted["jobId"]);
    }
}

#[tokio::test]
async fn ordinary_image_gaussian_blur_curves_export_selected_local_clock() {
    use video_kadr_backend::domain::composition::{CanvasSpec, Composition, TransformSpec};
    for tool in ["ffmpeg", "ffprobe"] {
        assert!(std::process::Command::new(tool).arg("-version").output().unwrap().status.success());
    }
    let (state, _directory) = make_state(true, true).await;
    image::RgbaImage::from_raw(16,16,[255,255,255,128].repeat(256)).unwrap()
        .save(state.sources_dir().join("effect-image.png")).unwrap();
    assert!(state.library.add(MediaEntry::from_result("source", &json!({"id":"effect-image","filename":"effect-image.png","url":"/files/sources/effect-image.png","mediaType":"image"}))).await);
    let mut canvas=CanvasSpec::default();canvas.width=16;canvas.height=16;canvas.fps_milli=10000;
    let mut content=Composition::new(canvas);
    content.sources=serde_json::from_value(json!({"effect-image":{"id":"effect-image","kind":"image","durationTicks":0,"width":16,"height":16,"hasAudio":false}})).unwrap();
    content.tracks=serde_json::from_value(json!([{"kind":"image","id":"images","name":"Images","clips":[{"id":"photo","sourceId":"effect-image","timelineStartTick":1000000,"durationTicks":1000000,"transform":TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal","effects":[{"kind":"gamma_correction","parameters":{},"animation":{"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":10.0},{"tick":500000,"value":20.0}]}}}]}]}])).unwrap();
    let app=router(state.clone());
    let oracle:Value=serde_json::from_str(include_str!("fixtures/filmcraft-gaussian-blur.json")).unwrap();
    assert_eq!(oracle["media"].as_array().unwrap().len(),18);
    let curve=json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0},{"tick":500000,"value":12}]}});
    let mut keyed=serde_json::to_value(&content).unwrap();
    for case in oracle["media"].as_array().unwrap() {
        keyed["tracks"][0]["clips"][0]["effects"]=json!([{"kind":"gaussian_blur","parameters":{"dimensions":case["dimensions"],"repeatEdge":case["repeatEdge"]},"animation":curve}]);
        let start=1000000+case["localTick"].as_u64().unwrap();
        let bits:Vec<u32>=serde_json::from_value(case["bits"].clone()).unwrap();
        let expected:Vec<[u8;3]>=bits.chunks_exact(4).map(|p|{
            let a=f32::from_bits(p[3]);let alpha=(a*255.0+1e-4).round().clamp(0.0,255.0);
            std::array::from_fn(|c|{
                if a<=1e-6 {return 0;}
                let v=(f32::from_bits(p[c])/a).max(0.0);
                let display=if v<=0.0031308 {v*12.92}else{1.055*v.powf(1.0/2.4)-0.055};
                (((display*255.0+1e-4).round().clamp(0.0,255.0))*alpha/255.0).round() as u8
            })
        }).collect();
        let native_composition:Composition=serde_json::from_value(keyed.clone()).unwrap();
        let mut decoder=|_:&video_kadr_backend::domain::composition::SourceId|Ok(video_kadr_backend::domain::group_surface::GroupSurface{width:16,height:16,rgba:[255,255,255,128].repeat(256)});
        let native=video_kadr_backend::domain::flat_surface::render_generated_images(&native_composition,start,&mut||Ok(()),Some(&mut decoder)).unwrap().unwrap();
        for (index,(pixel,rgb)) in native.rgba.chunks_exact(4).zip(expected.iter()).enumerate() {
            for c in 0..3 {assert!((i16::from(pixel[c])-i16::from(rgb[c])).abs()<=1,"Gaussian native before encoding dimensions {} repeat {} selected {start} pixel{index}: {pixel:?} expected {rgb:?}",case["dimensions"],case["repeatEdge"]);}
        }
        let body=json!({"schemaVersion":1,"composition":keyed,"output":{"profile":{"container":"mp4","codec":"h264"},"range":{"startTicks":start,"endTicks":2000000}}});
        let (status,accepted,_)=send(&app,post_json("/api/compositions/render",body.clone())).await;
        assert_eq!(status,StatusCode::ACCEPTED,"{accepted}");
        let done=poll_terminal(&app,accepted["jobId"].as_str().unwrap()).await;
        assert_eq!(done["status"],"done","Gaussian Blur image export: {done}");
        let output=state.outputs_dir().join(done["result"]["filename"].as_str().unwrap());
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&output,0,16,16).unwrap();
        // Measure delivery against independently encoded upstream RGB, not an assumed universal pixel tolerance.
        // The strict native and FFV1 tests independently guard the effect and selected-range timing.
        let raw_path=state.outputs_dir().join("gaussian-upstream.rgb");
        let reference_path=state.outputs_dir().join("gaussian-upstream.mp4");
        let raw:Vec<u8>=expected.iter().flatten().copied().collect();std::fs::write(&raw_path,raw).unwrap();
        let encoded=std::process::Command::new("ffmpeg").args(["-v","error","-y","-f","rawvideo","-pixel_format","rgb24","-video_size","16x16","-framerate","10","-i"]).arg(&raw_path).args(["-c:v","libx264","-preset","veryfast","-crf","23","-pix_fmt","yuv420p"]).arg(&reference_path).output().unwrap();
        assert!(encoded.status.success(),"{}",String::from_utf8_lossy(&encoded.stderr));
        let reference=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&reference_path,0,16,16).unwrap();
        let metrics=|rgba:&[u8]| {
            let mut peak=0u8;let mut squared=0.0;
            for (pixel,rgb) in rgba.chunks_exact(4).zip(&expected) {assert_eq!(pixel[3],255);for c in 0..3 {let error=pixel[c].abs_diff(rgb[c]);peak=peak.max(error);squared+=f64::from(error).powi(2);}}
            (peak,squared/(256.0*3.0))
        };
        let (peak,mse)=metrics(&frame.rgba);let (reference_peak,reference_mse)=metrics(&reference.rgba);
        eprintln!("Gaussian delivery {start} dimensions{} repeat{} peak{peak} mse{mse:.3}; independent codec peak{reference_peak} mse{reference_mse:.3}",case["dimensions"],case["repeatEdge"]);
        // Permit at most 2 extra peak levels and 1dB of mean error from sequence encoder decisions.
        assert!(peak<=reference_peak.saturating_add(2)&&mse<=reference_mse*10.0f64.powf(0.1)+1.0,"delivery exceeds independent codec error: peak{peak}/{reference_peak} mse{mse}/{reference_mse}");
        let (_,reused,_)=send(&app,post_json("/api/compositions/render",body)).await;
        assert_eq!(reused["jobId"],accepted["jobId"]);
    }
}

#[tokio::test]
async fn ordinary_image_gaussian_blur_lossless_selected_local_clock() {
    use video_kadr_backend::domain::composition::{CanvasSpec, Composition, TransformSpec};
    for tool in ["ffmpeg", "ffprobe"] {
        assert!(std::process::Command::new(tool).arg("-version").output().unwrap().status.success());
    }
    let (state, _directory) = make_state(true, true).await;
    image::RgbaImage::from_raw(16,16,[255,255,255,128].repeat(256)).unwrap()
        .save(state.sources_dir().join("effect-image.png")).unwrap();
    assert!(state.library.add(MediaEntry::from_result("source", &json!({"id":"effect-image","filename":"effect-image.png","url":"/files/sources/effect-image.png","mediaType":"image"}))).await);
    let mut canvas=CanvasSpec::default();canvas.width=16;canvas.height=16;canvas.fps_milli=10000;
    let mut content=Composition::new(canvas);
    content.sources=serde_json::from_value(json!({"effect-image":{"id":"effect-image","kind":"image","durationTicks":0,"width":16,"height":16,"hasAudio":false}})).unwrap();
    content.tracks=serde_json::from_value(json!([{"kind":"image","id":"images","name":"Images","clips":[{"id":"photo","sourceId":"effect-image","timelineStartTick":1000000,"durationTicks":1000000,"transform":TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal","effects":[{"kind":"gamma_correction","parameters":{},"animation":{"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":10.0},{"tick":500000,"value":20.0}]}}}]}]}])).unwrap();
    let oracle:Value=serde_json::from_str(include_str!("fixtures/filmcraft-gaussian-blur.json")).unwrap();
    assert_eq!(oracle["media"].as_array().unwrap().len(),18);
    let curve=json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":0},{"tick":500000,"value":12}]}});
    let mut keyed=serde_json::to_value(&content).unwrap();
    for case in oracle["media"].as_array().unwrap() {
        keyed["tracks"][0]["clips"][0]["effects"]=json!([{"kind":"gaussian_blur","parameters":{"dimensions":case["dimensions"],"repeatEdge":case["repeatEdge"]},"animation":curve}]);
        let start=1000000+case["localTick"].as_u64().unwrap();
        let bits:Vec<u32>=serde_json::from_value(case["bits"].clone()).unwrap();
        let expected:Vec<[u8;3]>=bits.chunks_exact(4).map(|p|{
            let a=f32::from_bits(p[3]);let alpha=(a*255.0+1e-4).round().clamp(0.0,255.0);
            std::array::from_fn(|c|{
                if a<=1e-6 {return 0;}
                let v=(f32::from_bits(p[c])/a).max(0.0);
                let display=if v<=0.0031308 {v*12.92}else{1.055*v.powf(1.0/2.4)-0.055};
                (((display*255.0+1e-4).round().clamp(0.0,255.0))*alpha/255.0).round() as u8
            })
        }).collect();
        let native_composition:Composition=serde_json::from_value(keyed.clone()).unwrap();
        let mut decoder=|_:&video_kadr_backend::domain::composition::SourceId|Ok(video_kadr_backend::domain::group_surface::GroupSurface{width:16,height:16,rgba:[255,255,255,128].repeat(256)});
        let native=video_kadr_backend::domain::flat_surface::render_generated_images(&native_composition,start,&mut||Ok(()),Some(&mut decoder)).unwrap().unwrap();
        for (index,(pixel,rgb)) in native.rgba.chunks_exact(4).zip(expected.iter()).enumerate() {
            for c in 0..3 {assert!((i16::from(pixel[c])-i16::from(rgb[c])).abs()<=1,"Gaussian native before encoding dimensions {} repeat {} selected {start} pixel{index}: {pixel:?} expected {rgb:?}",case["dimensions"],case["repeatEdge"]);}
        }
        let inputs=std::collections::BTreeMap::from([(native_composition.sources.keys().next().unwrap().clone(),state.sources_dir().join("effect-image.png"))]);
        let(progress,_receiver)=tokio::sync::mpsc::unbounded_channel();
        let movie=video_kadr_backend::tools::composition_native_video::prepare_native_video(&state.process_runtime,&state.outputs_dir(),&native_composition,&inputs,start..2000000,std::time::Duration::from_secs(30),&tokio_util::sync::CancellationToken::new(),&progress).await.unwrap();
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),movie.path(),0,16,16).unwrap();
        assert_eq!(frame.rgba,native.rgba,"lossless selected frame mismatch {start} dimensions {} repeat {}",case["dimensions"],case["repeatEdge"]);
    }
}

