        for (index,(pixel,rgb)) in native.rgba.chunks_exact(4).zip(expected.iter()).enumerate() {
            for c in 0..3 {assert!((i16::from(pixel[c])-i16::from(rgb[c])).abs()<=1,"GrowShrink native before encoding dimensions {} repeat {} selected {start} pixel{index}: {pixel:?} expected {rgb:?}",case["localTick"],case["localTick"]);}
        }
