#[tokio::test]
async fn ordinary_image_rounded_crop_lossless_selected_local_clock() {
    use video_kadr_backend::domain::composition::{CanvasSpec, Composition, TransformSpec};
    for tool in ["ffmpeg", "ffprobe"] {
        assert!(std::process::Command::new(tool).arg("-version").output().unwrap().status.success());
    }
    let (state, _directory) = make_state(true, true).await;
    image::RgbaImage::from_raw(16,16,(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,if i%16<8&&i/16<12 {128}else{0}]}).collect()).unwrap()
        .save(state.sources_dir().join("effect-image.png")).unwrap();
    assert!(state.library.add(MediaEntry::from_result("source", &json!({"id":"effect-image","filename":"effect-image.png","url":"/files/sources/effect-image.png","mediaType":"image"}))).await);
    let mut canvas=CanvasSpec::default();canvas.width=16;canvas.height=16;canvas.fps_milli=10000;
    let mut content=Composition::new(canvas);
    content.sources=serde_json::from_value(json!({"effect-image":{"id":"effect-image","kind":"image","durationTicks":0,"width":16,"height":16,"hasAudio":false}})).unwrap();
    content.tracks=serde_json::from_value(json!([{"kind":"image","id":"images","name":"Images","clips":[{"id":"photo","sourceId":"effect-image","timelineStartTick":1000000,"durationTicks":1000000,"transform":TransformSpec::default(),"opacity":{"mode":"constant","value":1.0},"blendMode":"normal","effects":[]}]}])).unwrap();
    let oracle:Value=serde_json::from_str(include_str!("fixtures/filmcraft-rounded-crop.json")).unwrap();
    assert_eq!(oracle["media"].as_array().unwrap().len(),12);
    let scalar=|a:f64,b:f64|json!({"mode":"keyframes","track":{"timeBase":1000000,"interpolation":"linear","keyframes":[{"tick":0,"value":a},{"tick":500000,"value":b}]}});
    let mut keyed=serde_json::to_value(&content).unwrap();
    for case in oracle["media"].as_array().unwrap() {
        let curve=json!({"left":scalar(0.,20.),"top":scalar(0.,10.),"right":scalar(0.,5.),"bottom":scalar(0.,15.),"radius":scalar(0.,4.),"feather":scalar(0.,case["feather"].as_f64().unwrap()),"border":scalar(0.,case["border"].as_f64().unwrap()),"borderR":scalar(0.,1.),"borderG":scalar(1.,0.),"borderB":scalar(0.25,0.75),"borderA":scalar(0.,1.)});
        keyed["tracks"][0]["clips"][0]["effects"]=json!([{"kind":"rounded_crop","parameters":{},"animation":curve}]);
        let start=1000000+case["localTick"].as_u64().unwrap();
        let bits:Vec<u32>=serde_json::from_value(case["bits"].clone()).unwrap();
        let expected:Vec<[u8;3]>=bits.chunks_exact(4).map(|p|{
            let a=f32::from_bits(p[3]);let alpha=(a*255.0+1e-4).round().clamp(0.0,255.0);
            std::array::from_fn(|c|{
                if a<=1e-6 {return 0;}
                let v=(f32::from_bits(p[c])/a).max(0.0);
                let display=if v<=0.0031308 {v*12.92}else{1.055*v.powf(1.0/2.4)-0.055};
                (((display*255.0+1e-4).round().clamp(0.0,255.0))*alpha/255.0).round() as u8
            })
        }).collect();
        let native_composition:Composition=serde_json::from_value(keyed.clone()).unwrap();
        let mut decoder=|_:&video_kadr_backend::domain::composition::SourceId|Ok(video_kadr_backend::domain::group_surface::GroupSurface{width:16,height:16,rgba:(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,if i%16<8&&i/16<12 {128}else{0}]}).collect()});
        let native=video_kadr_backend::domain::flat_surface::render_generated_images(&native_composition,start,&mut||Ok(()),Some(&mut decoder)).unwrap().unwrap();
        for (index,(pixel,rgb)) in native.rgba.chunks_exact(4).zip(expected.iter()).enumerate() {
            for c in 0..3 {assert!((i16::from(pixel[c])-i16::from(rgb[c])).abs()<=1,"RoundedCrop native before encoding dimensions {} repeat {} selected {start} pixel{index}: {pixel:?} expected {rgb:?}",case["localTick"],case["localTick"]);}
        }
        let inputs=std::collections::BTreeMap::from([(native_composition.sources.keys().next().unwrap().clone(),state.sources_dir().join("effect-image.png"))]);
        let(progress,_receiver)=tokio::sync::mpsc::unbounded_channel();
        let movie=video_kadr_backend::tools::composition_native_video::prepare_native_video(&state.process_runtime,&state.outputs_dir(),&native_composition,&inputs,start..2000000,std::time::Duration::from_secs(30),&tokio_util::sync::CancellationToken::new(),&progress).await.unwrap();
        let frame=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),movie.path(),0,16,16).unwrap();
        assert_eq!(frame.rgba,native.rgba,"lossless selected frame mismatch {start} dimensions {} repeat {}",case["localTick"],case["localTick"]);
        let decoded=std::process::Command::new("ffmpeg").args(["-v","error","-i"]).arg(movie.path()).args(["-f","rawvideo","-pix_fmt","rgba","pipe:1"]).output().unwrap();
        assert!(decoded.status.success(),"{}",String::from_utf8_lossy(&decoded.stderr));
        let frames:Vec<Vec<u32>>=serde_json::from_value(case["frames"].clone()).unwrap();
        assert_eq!(decoded.stdout.len(),frames.len()*16*16*4,"selected sequence frame count {start}");
        for(index,bits)in frames.iter().enumerate() {
            let tick=start+index as u64*100000;
            let native=video_kadr_backend::domain::flat_surface::render_generated_images(&native_composition,tick,&mut||Ok(()),Some(&mut decoder)).unwrap().unwrap();
            let encoded=&decoded.stdout[index*1024..(index+1)*1024];
            assert_eq!(encoded,native.rgba,"lossless RoundedCrop sequence {start} frame{index}");
            for(pixel,bits)in native.rgba.chunks_exact(4).zip(bits.chunks_exact(4)) {
                let a=f32::from_bits(bits[3]);let alpha=(a*255.0+1e-4).round().clamp(0.0,255.0);
                for c in 0..3 {
                    let expected=if a<=1e-6 {0}else{let v=(f32::from_bits(bits[c])/a).max(0.0);let display=if v<=0.0031308 {v*12.92}else{1.055*v.powf(1.0/2.4)-0.055};((display*255.0+1e-4).round().clamp(0.0,255.0)*alpha/255.0).round()as u8};
                    assert!((i16::from(pixel[c])-i16::from(expected)).abs()<=1,"original RoundedCrop sequence {start} frame{index} channel{c}");
                }
                assert_eq!(pixel[3],255);
            }
        }

    }
}

