        assert!(encoded.status.success(),"{}",String::from_utf8_lossy(&encoded.stderr));
        let reference=video_kadr_backend::domain::group_media::decode_rendered_frame(std::path::Path::new("ffmpeg"),&reference_path,0,16,16).unwrap();
